1	import { decodeCanonical, encodeCanonical, hashDomain } from "@ts-drp/canonical";
2	
3	import { settlementProfileFor } from "./settlement-profile.js";
4	
5	const AUTHOR = /^[0-9a-f]{64}$/u;
6	const OBJECT_ID = /^[A-Za-z0-9._:-]{1,256}$/u;
7	const GROUPS_V1 = ["admin", "finality", "writer"] as const;
8	const GROUPS_V2 = ["admin", "finality", "referee", "writer"] as const;
9	const SNAPSHOT_KEYS = ["epoch", "kind", "members", "objectId", "permissionless", "version"] as const;
10	const MEMBER_KEYS = ["author", "finalityKey", "groups"] as const;
11	const AUTHORITY_INPUT_KEYS = ["author", "snapshot"] as const;
12	const STAGE_INPUT_KEYS = ["operations", "snapshot"] as const;
13	const SIGNER_INPUT_KEYS = ["snapshot"] as const;
14	const GRANT_REVOKE_KEYS = ["actor", "group", "kind", "target"] as const;
15	const SET_KEY_KEYS = ["actor", "finalityKey", "kind"] as const;
16	const OPEN_KEYS = ["exactCanonicalLatchedAclBytes", "expectedAclDigest", "expectedEpoch", "expectedObjectId"] as const;
17	const OPEN_KEYS_WITH_PROFILE = [...OPEN_KEYS, "expectedProfileId"] as const;
18	const DIGEST = /^[0-9a-f]{64}$/u;
19	const MAX_CANONICAL_BYTES = 8192;
20	const MAX_CANONICAL_ITEMS = 2048;
21	const SETTLEMENT_MAX_CANONICAL_BYTES = 65_536;
22	const SETTLEMENT_MAX_CANONICAL_ITEMS = 8192;
23	
24	export type LatchedAclGroup = (typeof GROUPS_V2)[number];
25	
26	export type LatchedAclMember = Readonly<{
27		readonly author: string;
28		readonly finalityKey: string | null;
29		readonly groups: readonly LatchedAclGroup[];
30	}>;
31	
32	export type LatchedAclSnapshot = Readonly<{
33		readonly epoch: number;
34		readonly kind: "drp-v3-latched-acl";
35		readonly members: readonly LatchedAclMember[];
36		readonly objectId: string;
37		readonly permissionless: boolean;
38		readonly version: 1 | 2 | 3;
39	}>;
40	
41	export type LatchedAclOperation =
42		| Readonly<{
43				actor: string;
44				group: LatchedAclGroup;
45				kind: "grant" | "revoke";
46				target: string;
47		  }>
48		| Readonly<{
49				actor: string;
50				finalityKey: string;
51				kind: "set-finality-key";
52		  }>;
53	
54	export type LatchedAclAuthorityResult =
55		| Readonly<{ ok: false; reason: "malformed-input" }>
56		| Readonly<{ authorized: boolean; ok: true }>;
57	
58	export type StageLatchedAclResult =
59		| Readonly<{
60				index: number;
61				ok: false;
62				reason: "last-admin" | "malformed-input" | "operation-invalid" | "operation-not-authorized";
63		  }>
64		| Readonly<{ next: LatchedAclSnapshot; ok: true }>;
65	
66	export type DeriveLatchedSignerSetResult =
67		| Readonly<{ ok: false; reason: "malformed-input" }>
68		| Readonly<{
69				ok: true;
70				signers: readonly Readonly<{ publicKey: string; signerId: string }>[];
71		  }>;
72	
73	export type OpenCanonicalLatchedAclResult =
74		| Readonly<{ ok: false; reason: "malformed-input" | "snapshot-mismatch" }>
75		| Readonly<{ ok: true; snapshot: LatchedAclSnapshot }>;
76	
77	interface MutableMember {
78		readonly author: string;
79		finalityKey: string | null;
80		readonly groups: Set<LatchedAclGroup>;
81	}
82	
83	interface OpenedSnapshotState {
84		readonly membersByAuthor: ReadonlyMap<string, LatchedAclMember>;
85	}
86	
87	const openedSnapshots = new WeakMap<LatchedAclSnapshot, OpenedSnapshotState>();
88	
89	function exactDataRecord(value: unknown, keys: readonly string[]): Record<string, unknown> | undefined {
90		if (typeof value !== "object" || value === null || Array.isArray(value)) return undefined;
91		const prototype = Object.getPrototypeOf(value);
92		if (prototype !== Object.prototype && prototype !== null) return undefined;
93		const actualKeys = Reflect.ownKeys(value);
94		if (actualKeys.length !== keys.length || actualKeys.some((key) => typeof key !== "string" || !keys.includes(key))) {
95			return undefined;
96		}
97		const output: Record<string, unknown> = Object.create(null) as Record<string, unknown>;
98		for (const key of keys) {
99			const descriptor = Object.getOwnPropertyDescriptor(value, key);
100			if (descriptor === undefined || !("value" in descriptor) || descriptor.enumerable !== true) {
101				return undefined;
102			}
103			output[key] = descriptor.value;
104		}
105		return output;
106	}
107	
108	function compareText(left: string, right: string): number {
109		return left < right ? -1 : left > right ? 1 : 0;
110	}
111	
112	function sameBytes(left: Uint8Array, right: Uint8Array): boolean {
113		return left.byteLength === right.byteLength && left.every((value, index) => value === right[index]);
114	}
115	
116	function lowerHex(bytes: Uint8Array): string {
117		return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
118	}
119	
120	function groupsForVersion(version: LatchedAclSnapshot["version"]): readonly LatchedAclGroup[] {
121		return version === 1 ? GROUPS_V1 : GROUPS_V2;
122	}
123	
124	function isGroup(value: unknown, version: LatchedAclSnapshot["version"]): value is LatchedAclGroup {
125		return typeof value === "string" && groupsForVersion(version).includes(value as LatchedAclGroup);
126	}
127	
128	function copySnapshot(value: unknown): LatchedAclSnapshot | undefined {
129		if (typeof value === "object" && value !== null && openedSnapshots.has(value as LatchedAclSnapshot)) {
130			return value as LatchedAclSnapshot;
131		}
132		const record = exactDataRecord(value, SNAPSHOT_KEYS);
133		if (
134			record === undefined ||
135			record.kind !== "drp-v3-latched-acl" ||
136			(record.version !== 1 && record.version !== 2 && record.version !== 3) ||
137			typeof record.epoch !== "number" ||
138			!Number.isSafeInteger(record.epoch) ||
139			record.epoch < 0 ||
140			typeof record.objectId !== "string" ||
141			!OBJECT_ID.test(record.objectId) ||
142			typeof record.permissionless !== "boolean" ||
143			!Array.isArray(record.members) ||
144			record.members.length === 0 ||
145			record.members.length > (record.version === 3 ? 256 : 64)
146		) {
147			return undefined;
148		}
149		const version = record.version;
150		const groupsForSnapshot = groupsForVersion(version);
151		const members: LatchedAclMember[] = [];
152		let previousAuthor = "";
153		for (const valueMember of record.members) {
154			const selected = exactDataRecord(valueMember, MEMBER_KEYS);
155			if (
156				selected === undefined ||
157				typeof selected.author !== "string" ||
158				!AUTHOR.test(selected.author) ||
159				selected.author <= previousAuthor ||
160				!Array.isArray(selected.groups) ||
161				selected.groups.length === 0 ||
162				selected.groups.length > groupsForSnapshot.length ||
163				(selected.finalityKey !== null &&
164					(typeof selected.finalityKey !== "string" || !AUTHOR.test(selected.finalityKey)))
165			) {
166				return undefined;
167			}
168			const groups: LatchedAclGroup[] = [];
169			let previousGroup = -1;
170			for (const valueGroup of selected.groups) {
171				if (typeof valueGroup !== "string" || !groupsForSnapshot.includes(valueGroup as LatchedAclGroup)) {
172					return undefined;
173				}
174				const index = groupsForSnapshot.indexOf(valueGroup as LatchedAclGroup);
175				if (index <= previousGroup) return undefined;
176				previousGroup = index;
177				groups.push(valueGroup as LatchedAclGroup);
178			}
179			if (selected.finalityKey !== null && !groups.includes("finality")) return undefined;
180			previousAuthor = selected.author;
181			members.push(
182				Object.freeze({
183					author: selected.author,
184					finalityKey: selected.finalityKey,
185					groups: Object.freeze(groups),
186				})
187			);
188		}
189		if (!members.some(({ groups }) => groups.includes("admin"))) return undefined;
190		const snapshot = Object.freeze({
191			epoch: record.epoch,
192			kind: "drp-v3-latched-acl",
193			members: Object.freeze(members),
194			objectId: record.objectId,
195			permissionless: record.permissionless,
196			version,
197		});
198		openedSnapshots.set(
199			snapshot,
200			Object.freeze({ membersByAuthor: new Map(members.map((member) => [member.author, member])) })
201		);
202		return snapshot;
203	}
204	
205	/**
206	 * Opens one canonical current-epoch ACL snapshot against anchor-bound identity.
207	 * @param input - Exact carrier bytes and the authenticated anchor expectations.
208	 * @returns A detached snapshot or a closed fail-closed result.
209	 */
210	export function openCanonicalLatchedAclSnapshot(
211		input: Readonly<{
212			readonly exactCanonicalLatchedAclBytes: Uint8Array;
213			readonly expectedAclDigest: string;
214			readonly expectedEpoch: number;
215			readonly expectedObjectId: string;
216			readonly expectedProfileId?: string;
217		}>
218	): OpenCanonicalLatchedAclResult {
219		try {
220			const record = exactDataRecord(input, OPEN_KEYS) ?? exactDataRecord(input, OPEN_KEYS_WITH_PROFILE);
221			const settlementProfile =
222				record !== undefined && typeof record.expectedProfileId === "string"
223					? settlementProfileFor(record.expectedProfileId)
224					: "none";
225			const maximumBytes = settlementProfile === "v1" ? SETTLEMENT_MAX_CANONICAL_BYTES : MAX_CANONICAL_BYTES;
226			if (
227				record === undefined ||
228				!(record.exactCanonicalLatchedAclBytes instanceof Uint8Array) ||
229				record.exactCanonicalLatchedAclBytes.byteLength === 0 ||
230				record.exactCanonicalLatchedAclBytes.byteLength > maximumBytes ||
231				typeof record.expectedAclDigest !== "string" ||
232				!DIGEST.test(record.expectedAclDigest) ||
233				typeof record.expectedEpoch !== "number" ||
234				!Number.isSafeInteger(record.expectedEpoch) ||
235				record.expectedEpoch < 0 ||
236				typeof record.expectedObjectId !== "string" ||
237				!OBJECT_ID.test(record.expectedObjectId)
238			) {
239				return Object.freeze({ ok: false, reason: "malformed-input" });
240			}
241			const exactBytes = new Uint8Array(record.exactCanonicalLatchedAclBytes);
242			const decoded = decodeCanonical(
243				exactBytes,
244				settlementProfile === "v1"
245					? { maxBytes: SETTLEMENT_MAX_CANONICAL_BYTES, maxDepth: 4, maxItems: SETTLEMENT_MAX_CANONICAL_ITEMS }
246					: { maxBytes: MAX_CANONICAL_BYTES, maxDepth: 4, maxItems: MAX_CANONICAL_ITEMS }
247			);
248			if (!sameBytes(encodeCanonical(decoded), exactBytes)) {
249				return Object.freeze({ ok: false, reason: "malformed-input" });
250			}
251			const snapshot = copySnapshot(decoded);
252			if (
253				snapshot === undefined ||
254				(snapshot.version === 3) !== (settlementProfile === "v1") ||
255				snapshot.epoch !== record.expectedEpoch ||
256				snapshot.objectId !== record.expectedObjectId ||
257				lowerHex(hashDomain("ts-drp/latched-acl/v3", exactBytes)) !== record.expectedAclDigest
258			) {
259				return Object.freeze({ ok: false, reason: "snapshot-mismatch" });
260			}
261			return Object.freeze({ ok: true, snapshot });
262		} catch {
263			return Object.freeze({ ok: false, reason: "malformed-input" });
264		}
265	}
266	
267	function mutableMembers(snapshot: LatchedAclSnapshot): Map<string, MutableMember> {
268		return new Map(
269			snapshot.members.map(({ author, finalityKey, groups }) => [
270				author,
271				{ author, finalityKey, groups: new Set(groups) },
272			])
273		);
274	}
275	
276	function copyOperation(value: unknown, version: LatchedAclSnapshot["version"]): LatchedAclOperation | undefined {
277		if (typeof value !== "object" || value === null) return undefined;
278		const kindDescriptor = Object.getOwnPropertyDescriptor(value, "kind");
279		if (kindDescriptor === undefined || !("value" in kindDescriptor)) return undefined;
280		if (kindDescriptor.value === "set-finality-key") {
281			const record = exactDataRecord(value, SET_KEY_KEYS);
282			if (
283				record === undefined ||
284				record.kind !== "set-finality-key" ||
285				typeof record.actor !== "string" ||
286				!AUTHOR.test(record.actor) ||
287				typeof record.finalityKey !== "string" ||
288				!AUTHOR.test(record.finalityKey)
289			) {
290				return undefined;
291			}
292			return Object.freeze({ actor: record.actor, finalityKey: record.finalityKey, kind: "set-finality-key" });
293		}
294		const record = exactDataRecord(value, GRANT_REVOKE_KEYS);
295		if (
296			record === undefined ||
297			(record.kind !== "grant" && record.kind !== "revoke") ||
298			typeof record.actor !== "string" ||
299			!AUTHOR.test(record.actor) ||
300			typeof record.target !== "string" ||
301			!AUTHOR.test(record.target) ||
302			!isGroup(record.group, version)
303		) {
304			return undefined;
305		}
306		return Object.freeze({ actor: record.actor, group: record.group, kind: record.kind, target: record.target });
307	}
308	
309	function authorityInput(value: unknown):
310		| Readonly<{
311				author: string;
312				membersByAuthor: ReadonlyMap<string, LatchedAclMember>;
313				snapshot: LatchedAclSnapshot;
314		  }>
315		| undefined {
316		const record = exactDataRecord(value, AUTHORITY_INPUT_KEYS);
317		const snapshot = record === undefined ? undefined : copySnapshot(record.snapshot);
318		const state = snapshot === undefined ? undefined : openedSnapshots.get(snapshot);
319		if (
320			record === undefined ||
321			snapshot === undefined ||
322			state === undefined ||
323			typeof record.author !== "string" ||
324			!AUTHOR.test(record.author)
325		) {
326			return undefined;
327		}
328		return Object.freeze({ author: record.author, membersByAuthor: state.membersByAuthor, snapshot });
329	}
330	
331	function authorityFailure(): LatchedAclAuthorityResult {
332		return Object.freeze({ ok: false, reason: "malformed-input" });
333	}
334	
335	/**
336	 * Determines whether an already-authenticated author belongs to the latched epoch ACL.
337	 * @param input - Candidate author and validated current-epoch snapshot.
338	 * @returns A fail-closed authority decision.
339	 */
340	export function authorizeLatchedEnvelopeAuthor(
341		input: Readonly<{
342			readonly author: string;
343			readonly snapshot: LatchedAclSnapshot;
344		}>
345	): LatchedAclAuthorityResult {
346		try {
347			const selected = authorityInput(input);
348			if (selected === undefined) return authorityFailure();
349			return Object.freeze({
350				authorized: selected.membersByAuthor.has(selected.author),
351				ok: true,
352			});
353		} catch {
354			return authorityFailure();
355		}
356	}
357	
358	/**
359	 * Determines whether an admitted author may execute an application write in the latched epoch.
360	 * @param input - Candidate author and validated current-epoch snapshot.
361	 * @returns A fail-closed application-writer decision.
362	 */
363	export function authorizeLatchedApplicationWrite(
364		input: Readonly<{
365			readonly author: string;
366			readonly snapshot: LatchedAclSnapshot;
367		}>
368	): LatchedAclAuthorityResult {
369		try {
370			const selected = authorityInput(input);
371			if (selected === undefined) return authorityFailure();
372			const member = selected.membersByAuthor.get(selected.author);
373			return Object.freeze({
374				authorized: member !== undefined && (selected.snapshot.permissionless || member.groups.includes("writer")),
375				ok: true,
376			});
377		} catch {
378			return authorityFailure();
379		}
380	}
381	
382	function failedStage(
383		index: number,
384		reason: "last-admin" | "malformed-input" | "operation-invalid" | "operation-not-authorized"
385	): StageLatchedAclResult {
386		return Object.freeze({ index, ok: false, reason });
387	}
388	
389	function freezeMembers(
390		members: Map<string, MutableMember>,
391		version: LatchedAclSnapshot["version"]
392	): readonly LatchedAclMember[] {
393		return Object.freeze(
394			[...members.values()]
395				.filter(({ finalityKey, groups }) => groups.size > 0 || finalityKey !== null)
396				.sort((left, right) => compareText(left.author, right.author))
397				.map(({ author, finalityKey, groups }) =>
398					Object.freeze({
399						author,
400						finalityKey,
401						groups: Object.freeze(
402							[...groups].sort(
403								(left, right) => groupsForVersion(version).indexOf(left) - groupsForVersion(version).indexOf(right)
404							)
405						),
406					})
407				)
408		);
409	}
410	
411	/**
412	 * Applies authorized ACL operations to an isolated next-epoch snapshot.
413	 * @param input - Latched snapshot and canonically ordered candidate operations.
414	 * @returns The detached next snapshot or the first fail-closed rejection.
415	 */
416	export function stageLatchedAclOperations(
417		input: Readonly<{
418			readonly operations: readonly LatchedAclOperation[];
419			readonly snapshot: LatchedAclSnapshot;
420		}>
421	): StageLatchedAclResult {
422		try {
423			const record = exactDataRecord(input, STAGE_INPUT_KEYS);
424			const snapshot = record === undefined ? undefined : copySnapshot(record.snapshot);
425			if (record === undefined || snapshot === undefined || !Array.isArray(record.operations)) {
426				return failedStage(0, "malformed-input");
427			}
428			const operations: LatchedAclOperation[] = [];
429			for (const [index, value] of record.operations.entries()) {
430				const operation = copyOperation(value, snapshot.version);
431				if (operation === undefined) return failedStage(index, "malformed-input");
432				operations.push(operation);
433			}
434			const latched = mutableMembers(snapshot);
435			for (const [index, operation] of operations.entries()) {
436				const actor = latched.get(operation.actor);
437				if (operation.kind === "set-finality-key") {
438					if (!actor?.groups.has("finality")) return failedStage(index, "operation-not-authorized");
439				} else {
440					if (!actor?.groups.has("admin")) return failedStage(index, "operation-not-authorized");
441					if (snapshot.permissionless && operation.group === "writer") {
442						return failedStage(index, "operation-invalid");
443					}
444				}
445			}
446	
447			const nextMembers = mutableMembers(snapshot);
448			for (const operation of operations) {
449				if (operation.kind !== "grant") continue;
450				const target = nextMembers.get(operation.target) ?? {
451					author: operation.target,
452					finalityKey: null,
453					groups: new Set<LatchedAclGroup>(),
454				};
455				target.groups.add(operation.group);
456				nextMembers.set(operation.target, target);
457			}
458			for (const operation of operations) {
459				if (operation.kind !== "set-finality-key") continue;
460				const actor = nextMembers.get(operation.actor);
461				if (actor === undefined) return failedStage(0, "operation-invalid");
462				actor.finalityKey = operation.finalityKey;
463			}
464			for (const operation of operations) {
465				if (operation.kind !== "revoke") continue;
466				const target = nextMembers.get(operation.target);
467				target?.groups.delete(operation.group);
468				if (target !== undefined && operation.group === "finality") target.finalityKey = null;
469			}
470			const frozenMembers = freezeMembers(nextMembers, snapshot.version);
471			if (!frozenMembers.some(({ groups }) => groups.includes("admin"))) {
472				const index = operations.findIndex((operation) => operation.kind === "revoke" && operation.group === "admin");
473				return failedStage(Math.max(0, index), "last-admin");
474			}
475			if (snapshot.epoch === Number.MAX_SAFE_INTEGER) {
476				return failedStage(0, "operation-invalid");
477			}
478			const next = copySnapshot(
479				Object.freeze({
480					epoch: snapshot.epoch + 1,
481					kind: "drp-v3-latched-acl",
482					members: frozenMembers,
483					objectId: snapshot.objectId,
484					permissionless: snapshot.permissionless,
485					version: snapshot.version,
486				})
487			);
488			if (next === undefined) return failedStage(0, "operation-invalid");
489			const settlement = next.version === 3;
490			const exactBytes = encodeCanonical(next);
491			const maximumBytes = settlement ? SETTLEMENT_MAX_CANONICAL_BYTES : MAX_CANONICAL_BYTES;
492			if (exactBytes.byteLength > maximumBytes) return failedStage(0, "operation-invalid");
493			decodeCanonical(exactBytes, {
494				maxBytes: maximumBytes,
495				maxDepth: 4,
496				maxItems: settlement ? SETTLEMENT_MAX_CANONICAL_ITEMS : MAX_CANONICAL_ITEMS,
497			});
498			return Object.freeze({ next, ok: true });
499		} catch {
500			return failedStage(0, "malformed-input");
501		}
502	}
503	
504	/**
505	 * Derives the ordered next-epoch seal signer set from a validated ACL snapshot.
506	 * @param input - Candidate next-epoch ACL snapshot.
507	 * @returns The sorted signer set or a malformed-input rejection.
508	 */
509	export function deriveNextLatchedSignerSet(
510		input: Readonly<{
511			readonly snapshot: LatchedAclSnapshot;
512		}>
513	): DeriveLatchedSignerSetResult {
514		try {
515			const record = exactDataRecord(input, SIGNER_INPUT_KEYS);
516			const snapshot = record === undefined ? undefined : copySnapshot(record.snapshot);
517			if (snapshot === undefined) return Object.freeze({ ok: false, reason: "malformed-input" });
518			return Object.freeze({
519				ok: true,
